(function(){
  // find the speaker section heading and its container
  const headings = [...document.querySelectorAll('*')].filter(el => el.children.length===0 && el.textContent.trim()==='講者資訊');
  if (!headings.length) return 'not found';
  let container = headings[0].closest('section') || headings[0].parentElement.parentElement;
  const cards = container.querySelectorAll('[class*="speaker"], [class*="card"]');
  const sample = cards[1] || cards[0];
  const info = {
    containerClass: container.className,
    totalCandidateCards: cards.length,
    sampleOuterHTML: sample ? sample.outerHTML.slice(0, 1500) : null,
    gridStyle: container.querySelector('[class*="grid"],[class*="list"]') ? getComputedStyle(container.querySelector('[class*="grid"],[class*="list"]')).display : null
  };
  return JSON.stringify(info, null, 1);
})();

(function(){
  const bios = [...document.querySelectorAll('*')].filter(el => el.children.length===0 && el.textContent.trim()==='簡介');
  if (!bios.length) return 'no 簡介 found, count=0';
  // walk up to find the repeating card wrapper (parent that has siblings with similar structure)
  let el = bios[1];
  let card = el;
  for (let i=0;i<6;i++){
    card = card.parentElement;
    if (!card) break;
  }
  const parent = bios[1].parentElement.parentElement.parentElement;
  return JSON.stringify({
    bioCount: bios.length,
    cardCandidateHTML: parent ? parent.outerHTML.slice(0,2000) : null,
    cardCandidateClass: parent ? parent.className : null
  }, null, 1);
})();

(function(){
  const heading = [...document.querySelectorAll('h1,h2,h3,h4,h5,h6,div,span')].find(el => el.textContent.trim()==='講者資訊' && el.children.length===0);
  if(!heading) return 'not found';
  // climb up to find the grid container (has many similar children)
  let node = heading;
  let gridContainer = null;
  for(let i=0;i<8;i++){
    node = node.parentElement;
    if(!node) break;
    if(node.children.length > 5) { gridContainer = node; break; }
  }
  if(!gridContainer) return 'no grid found';
  const style = getComputedStyle(gridContainer);
  const firstCard = gridContainer.children[1] || gridContainer.children[0];
  const cardStyle = firstCard ? getComputedStyle(firstCard) : null;
  const img = firstCard ? firstCard.querySelector('img') : null;
  return JSON.stringify({
    gridDisplay: style.display,
    gridTemplateColumns: style.gridTemplateColumns,
    gap: style.gap,
    cardCount: gridContainer.children.length,
    cardWidth: cardStyle ? cardStyle.width : null,
    cardBg: cardStyle ? cardStyle.backgroundColor : null,
    cardBorderRadius: cardStyle ? cardStyle.borderRadius : null,
    imgSrc: img ? img.src : 'NO IMG TAG',
    firstCardHTML: firstCard ? firstCard.outerHTML.slice(0,800) : null
  }, null, 1);
})();

(function(){
  const btns = [...document.querySelectorAll('button')].filter(b => b.textContent.trim()==='簡介');
  if(!btns.length) return 'no buttons';
  const btn = btns[1];
  // climb up up to 6 levels, print each level's tag/class/childCount
  let node = btn;
  const trail = [];
  for(let i=0;i<7;i++){
    if(!node) break;
    trail.push({tag: node.tagName, cls: node.className, childCount: node.children.length});
    node = node.parentElement;
  }
  return JSON.stringify(trail, null, 1);
})();

