72	  <header>
73	    <h1>AI <span>百人導師</span>團隊</h1>
74	    <p>集結各領域頂尖導師，一起探索 AI 時代的實戰智慧</p>
75	    <a class="join-link" href="{{ url_for('join_form') }}">我也是導師，我要加入 →</a>
76	  </header>
77	
78	  {% if mentors %}
79	  <div class="grid">
80	    {% for m in mentors %}
81	    <div class="card">
82	      <div class="photo"><img src="{{ url_for('static', filename='uploads/' ~ m.photo_filename) }}" alt="{{ m.name }}"></div>
83	      <div class="info">
84	        <h3>{{ m.name }}</h3>
85	        <div class="subtitle">
86	          {{ m.company_title }}{% if m.role_tag %}<br>{{ m.role_tag }}{% endif %}
87	        </div>
88	        <button class="bio-btn"
89	          data-name="{{ m.name }}"
90	          data-subtitle="{{ m.company_title }}{% if m.role_tag %} ｜ {{ m.role_tag }}{% endif %}"
91	          data-bio="{{ m.bio }}"
92	          data-contact="{{ m.contact_url or '' }}"
93	          onclick="openBio(this)">簡介</button>
94	      </div>
95	    </div>
96	    {% endfor %}
97	  </div>
98	  {% else %}
99	  <div class="empty">還沒有導師資料，敬請期待。</div>
100	  {% endif %}
101	
102	  <div class="modal-overlay" id="bioModal">
103	    <div class="modal">
104	      <h3 id="modalName"></h3>
105	      <div class="subtitle" id="modalSubtitle"></div>
106	      <div class="bio" id="modalBio"></div>
107	      <div class="contact" id="modalContact"></div>
108	      <button class="close-btn" onclick="closeBio()">關閉</button>
109	    </div>
110	  </div>
111	
112	<script>
113	function openBio(btn) {
114	  document.getElementById('modalName').textContent = btn.dataset.name;
115	  document.getElementById('modalSubtitle').textContent = btn.dataset.subtitle;
116	  var bioEl = document.getElementById('modalBio');
117	  bioEl.innerHTML = '';
118	  btn.dataset.bio.split(/\n\s*\n/).forEach(function(para) {
119	    if (para.trim()) {
120	      var p = document.createElement('p');
121	      p.textContent = para.trim();
122	      bioEl.appendChild(p);
123	    }
124	  });
125	  var contactEl = document.getElementById('modalContact');
126	  contactEl.innerHTML = '';
127	  if (btn.dataset.contact) {
128	    var a = document.createElement('a');
129	    a.href = btn.dataset.contact;
130	    a.target = '_blank';
131	    a.rel = 'noopener';
132	    a.textContent = btn.dataset.contact;
133	    contactEl.appendChild(a);
134	  }
135	  document.getElementById('bioModal').classList.add('open');
136	}
137	function closeBio() {
138	  document.getElementById('bioModal').classList.remove('open');
139	}
140	document.getElementById('bioModal').addEventListener('click', function(e) {
141	  if (e.target === this) closeBio();
142	});
143	</script>
144	</body>
145	</html>
